package com.fasterxml.jackson.core.json;

import com.fasterxml.jackson.core.*;
import com.fasterxml.jackson.core.io.*;
import com.fasterxml.jackson.core.io.IOContext;
import com.fasterxml.jackson.databind.ObjectMapper;
import java.io.*;
import java.io.ByteArrayOutputStream;
import java.io.IOException;
import java.math.*;
import java.math.BigDecimal;
import java.math.BigInteger;
import java.nio.charset.StandardCharsets;
import java.util.*;
import org.junit.*;
import org.junit.After;
import org.junit.Before;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

/**
 * Unit tests for UTF8JsonGenerator.writeRaw(String, int, int)
 */
public class UTF8JsonGenerator_writeRaw_TriageGen0Test {

    private ByteArrayOutputStream out;
    private UTF8JsonGenerator gen;
    private ObjectMapper mapper;

    @Before
    public void setUp() throws IOException {
        out = new ByteArrayOutputStream();
        mapper = new ObjectMapper();
        // Using the constructor: UTF8JsonGenerator(IOContext ctxt, int features, ObjectCodec codec, OutputStream out)
        gen = new UTF8JsonGenerator(IOContext.EMPTY, 0, mapper, out);
    }

    @After
    public void tearDown() throws IOException {
        gen.close();
    }

    @Test
    public void testWriteRaw_SimpleString() throws IOException {
        String text = "hello";
        gen.writeRaw(text, 0, text.length());
        gen.flush();
        assertEquals("hello", out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test
    public void testWriteRaw_WithOffsetAndLen() throws IOException {
        String text = "abcdef";
        // Write "bcd" (offset 1, len 3)
        gen.writeRaw(text, 1, 3);
        gen.flush();
        assertEquals("bcd", out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test
    public void testWriteRaw_EmptyString() throws IOException {
        String text = "";
        gen.writeRaw(text, 0, 0);
        gen.flush();
        assertEquals("", out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test
    public void testWriteRaw_LargeString_TriggersSegmentation() throws IOException {
        // The internal _charBuffer size is typically small. 
        // We create a string much larger than the buffer to trigger the 'while (len > 0)' loop segments.
        StringBuilder sb = new StringBuilder();
        for (int i = 0; i < 500; i++) {
            sb.append("abc");
        }
        String largeText = sb.toString();

        gen.writeRaw(largeText, 0, largeText.length());
        gen.flush();

        assertEquals(largeText, out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test
    public void testWriteRaw_BoundaryCondition_ExactBufferSize() throws IOException {
        // Testing the Math.min(buf.length, len) logic
        // We use a string that is exactly a multiple of a likely small buffer
        // Since we can't easily see the private _charBuffer size without reflection, 
        // we use a large enough string to ensure multiple iterations.
        String text = "1234567890"; 
        int repeat = 100;
        StringBuilder sb = new StringBuilder();
        for(int i=0; i<repeat; i++) sb.append(text);
        String longText = sb.toString();

        gen.writeRaw(longText, 0, longText.length());
        gen.flush();
        assertEquals(longText, out.toString(StandardCharsets.UTF_8.name()));
    }

    @Test
    public void testWriteRaw_SurrogatePairs() throws IOException {
        // Testing characters that might be affected by the segmentation logic
        // Emoji: 𝄞 (U+1D11E) is represented by \uD834\uDD1E
        String emoji = "\uD834\uDD1E"; 
        gen.writeRaw(emoji, 0, 2);
        gen.flush();

        // The output should be the UTF-8 encoding of the surrogate pair
        String expected = new String(out.toByteArray(), StandardCharsets.UTF_8);
        assertEquals(emoji, expected);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testWriteRaw_InvalidOffset() throws IOException {
        String text = "test";
        gen.writeRaw(text, 5, 2);
    }

    @Test(expected = IndexOutOfBoundsException.class)
    public void testWriteRaw_InvalidLen() throws IOException {
        String text = "test";
        // Offset 1, len 5 exceeds string length (4)
        gen.writeRaw(text, 1, 5);
    }
}
